export function completeTask(state,id,at){const task=state.tasks.find(t=>t.id===id);if(!task)throw Error('Task not found');if(task.done)return state;return {...state,tasks:state.tasks.map(t=>t.id===id?{...t,done:true,completedAt:at}:t),audit:[{id:'a'+state.audit.length,event:'Task completed: '+task.title,at},...state.audit]};}
export function addRecord(state,type,record){if(!['logs','incidents'].includes(type))throw Error('Invalid record type');if(!people.some(p=>p.id===record.person))throw Error('Choose a person');const note=String(record.note||'').trim();if(note.length<3||note.length>2000)throw Error('Enter a note between 3 and 2,000 characters');if(!record.id||state[type].some(x=>x.id===record.id))throw Error('Record already exists');return {...state,[type]:[{...record,note},...state[type]],audit:[{id:'a'+state.audit.length,event:type==='logs'?'Care note added':'Incident recorded',at:record.at},...state.audit]};}
export function csvCell(value){let s=String(value??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
export function exportCsv(state){return [['Type','Person','Category','Note','Recorded at','Author'],...state.logs.map(r=>['Care note',people.find(p=>p.id===r.person)?.name,r.category,r.note,r.at,r.author]),...state.incidents.map(r=>['Incident',people.find(p=>p.id===r.person)?.name,r.category,r.note,r.at,r.author])].map(row=>row.map(csvCell).join(',')).join('\r\n');}
